function addColumnIfMissing(database, tableName, columnName, definition) {
	const sqlIdentifier = /^[A-Za-z_][A-Za-z0-9_]*$/;
	if (!sqlIdentifier.test(tableName) || !sqlIdentifier.test(columnName)) throw new Error("Unsafe migration identifier");
	if (!database.prepare(`SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?`).get(tableName)) return;
	if (database.prepare(`PRAGMA table_info("${tableName}")`).all().some((column) => column.name === columnName)) return;
	database.exec(`ALTER TABLE "${tableName}" ADD COLUMN "${columnName}" ${definition}`);
}
