      DROP TABLE generation_task_events_schema38;
      DROP TABLE generation_provider_attempts_schema38;
      DROP TABLE media_publication_attempts_schema38;
      DROP TABLE generation_tasks_schema38;

      UPDATE sqlite_sequence
